def equation(gate_voltage_abs: np.ndarray, drain_voltage_abs: np.ndarray, parameters: np.ndarray) -> np.ndarray:
    """Modelo empírico bivariado para log10(|ID|/A)."""
    """Improved version of `equation_v1` with logarithmic transformation."""
    log_gate_voltage = np.log(gate_voltage_abs)
    log_drain_voltage = np.log(drain_voltage_abs)

    return parameters[0] + parameters[1] * log_gate_voltage + parameters[2] * log_drain_voltage + parameters[3] * (log_gate_voltage * log_drain_voltage)
